        \"\"\"Factory to create markdown element, handling Table specifically.\"\"\"
        if token.tag == \"table\":
            return TableElement()
        return super().create(markdown, token)

    def on_enter(self, context: MarkdownContext) -> None:
        self.style = context.enter_style(self.style_name)
